<template><ElConfigProvider namespace="kel"><section class="native-query-view"><header><div><h2>{{title}}</h2><small>{{subtitle}}</small></div><KsButton size="small" :loading="loading" @click="emit('refresh')">刷新</KsButton></header><div v-if="kind==='logs'" class="query-controls"><KsInput :modelValue="query.q||''" placeholder="搜索已采集日志" @update:modelValue="v=>emit('filter','q',v)" clearable/><select :value="query.level||''" @change="emit('filter','level',($event.target as HTMLSelectElement).value)"><option value="">所有等级</option><option>ERROR</option><option>WARN</option><option>INFO</option><option>DEBUG</option><option>TRACE</option></select><input type="datetime-local" aria-label="起始时间" :value="localTime(query.since)" @change="emit('filter','since',($event.target as HTMLInputElement).value)"/><input type="datetime-local" aria-label="结束时间" :value="localTime(query.until)" @change="emit('filter','until',($event.target as HTMLInputElement).value)"/></div><div v-if="error" class="error" role="alert">{{error}}</div>
<template v-if="kind==='logs'"><div class="native-query-logs"><div v-for="line in data.items||[]" :key="line.id" class="native-query-log"><span>{{new Date(line.timestamp).toLocaleString()}}</span><b :class="line.level.toLowerCase()">{{line.level}}</b><div><button @click="emit('navigate','/flows/executions/'+line.execution_id+'?tab=Logs'+(line.task_run_id?'&task_run='+encodeURIComponent(line.task_run_id):''))">{{line.execution_id.slice(0,12)}} / {{line.task_id||'execution'}} →</button><pre>{{line.message}}</pre></div></div><div v-if="!loading&&!data.items?.length" class="empty">没有匹配的已采集日志</div></div><footer><small>{{data.coverage}}</small><KsButton v-if="data.next_cursor" size="small" @click="emit('more')">加载更早日志</KsButton><KsButton v-if="data.items?.length" size="small" @click="download">导出当前结果</KsButton></footer></template>
<template v-else><div class="query-controls"><label>开始<input type="datetime-local" aria-label="聚合开始时间" :value="localTime(query.since)" @change="emit('filter','since',($event.target as HTMLInputElement).value)"/></label><label>结束<input type="datetime-local" aria-label="聚合结束时间" :value="localTime(query.until)" @change="emit('filter','until',($event.target as HTMLInputElement).value)"/></label><label>Flow Revision<input type="number" min="1" aria-label="聚合Flow版本" :value="query.revision" @change="emit('filter','revision',($event.target as HTMLInputElement).value)"/></label><small>{{query.since||query.until?'所选创建时间窗':'全部已记录时间'}} · 引擎与设备分开统计</small></div><div class="summary"><strong>{{data.total??'—'}}</strong><div><b>Execution</b><small>{{data.state_source||'尚无聚合结果'}}</small></div></div><div class="summary-columns"><section><h3>引擎状态</h3><button v-for="(count,state) in data.states||{}" :key="state" class="summary-state" @click="emit('state',String(state))"><span>{{state}}</span><i :style="{width:Math.max(0,Number(count)/Math.max(1,data.total)*100)+'%'}"/><b>{{count}}</b></button><p v-if="!Object.keys(data.states||{}).length" class="empty">没有执行记录</p></section><section><h3>设备结果</h3><div v-for="(count,state) in data.targets||{}" :key="state" class="summary-state"><span>{{state}}</span><b>{{count}}</b></div><p v-if="!Object.keys(data.targets||{}).length" class="empty">没有设备目标记录</p></section></div><section v-if="kind==='metrics'" class="duration"><h3>执行耗时 · 秒</h3><div class="duration-values"><span>已采集完成样本 <b>{{data.duration?.sample_count??'—'}} / {{data.total??'—'}}</b></span><span>平均 <b>{{seconds(data.duration?.mean_seconds)}}</b></span><span>P50 <b>{{seconds(data.duration?.p50_seconds)}}</b></span><span>P95 <b>{{seconds(data.duration?.p95_seconds)}}</b></span></div><small>{{data.duration?.coverage||'尚未收到完成时间证据；不把缺测当成0秒。'}}</small><h3>执行趋势 · UTC 创建日</h3><svg v-if="trend.length" class="trend-svg" viewBox="0 0 1000 140" role="img" aria-label="每日执行次数与失败次数"><g v-for="(day,index) in trend" :key="day.date"><rect :x="(index+0.5)*1000/trend.length-Math.min(28,Math.max(1,1000/trend.length-3))/2" :y="130-day.total/peak*110" :width="Math.min(28,Math.max(1,1000/trend.length-3))" :height="day.total/peak*110" fill="var(--ks-text-link)" opacity="0.55"><title>{{day.date}} · {{day.total}} executions / {{day.failed}} FAILED</title></rect><rect :x="(index+0.5)*1000/trend.length-Math.min(28,Math.max(1,1000/trend.length-3))/2" :y="130-day.failed/peak*110" :width="Math.min(28,Math.max(1,1000/trend.length-3))" :height="day.failed/peak*110" fill="#c84f70"/></g></svg><p v-else class="empty">该范围没有执行记录</p><div v-if="trend.length" class="trend-labels"><span>{{trend[0].date}}</span><span>紫：执行 / 红：FAILED · 最近90个有记录UTC日，缺日不补零</span><span>{{trend.at(-1).date}}</span></div></section><template v-if="kind==='concurrency'"><div class="limits"><div><small>Flow 并发限制</small><b>{{limit??'未指定'}}</b></div><div><small>运行中</small><b>{{data.states?.RUNNING||0}}</b></div><div><small>队列</small><b>{{data.states?.QUEUED||0}}</b></div></div><p class="note">限制来自 Flow 定义；排队原因未由引擎报告时不推断。修改限制进入编辑器，保存新 Revision 后生效。</p><KsButton @click="emit('edit')">编辑并发限制</KsButton></template></template>
</section></ElConfigProvider></template>
<script setup lang="ts">
import {computed} from 'vue';
import {ElConfigProvider} from 'element-plus';import KsButton from '../../vendor/kestra/design-system/components/Basic/KsButton/KsButton.vue';import KsInput from '../../vendor/kestra/design-system/components/Form/KsInput.vue';
const props=defineProps<{kind:string;title:string;subtitle:string;loading:boolean;error:string;data:any;query:Record<string,string>;limit?:number}>(),emit=defineEmits(['refresh','filter','navigate','more','state','edit']);
const seconds=(v:any)=>typeof v==='number'?v.toFixed(2):'未采集 / 样本不足',trend=computed(()=>(props.data.daily||[]).slice(-90)),peak=computed(()=>Math.max(1,...trend.value.map((d:any)=>d.total)));
const localTime=(v?:string)=>{if(!v)return '';const d=new Date(v);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};
function download(){const url=URL.createObjectURL(new Blob([JSON.stringify(props.data.items,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='authorized-log-search.json';a.click();URL.revokeObjectURL(url)}
</script>
<style scoped>.native-query-view{color:var(--ks-text-primary);background:var(--ks-bg-surface);font:12px var(--ks-font-family-sans);padding:18px 20px;min-height:460px}header{display:flex;justify-content:space-between;align-items:center;padding-bottom:18px}h2{font-size:18px;margin:0 0 5px}small{font-size:10px;color:var(--ks-text-secondary)}.query-controls{display:flex;gap:8px;flex-wrap:wrap;padding:12px 0;border-block:1px solid var(--ks-border-default)}.query-controls>.kel-input{max-width:350px}.query-controls select,.query-controls input{background:var(--ks-bg-input);border:1px solid var(--ks-border-default);border-radius:4px;padding:6px;color:inherit;font-size:11px}.native-query-logs{max-height:550px;overflow:auto}.native-query-log{display:grid;grid-template-columns:160px 55px 1fr;gap:15px;border-bottom:1px solid var(--ks-border-default);padding:12px 0;font-size:11px}.native-query-log>span{color:var(--ks-text-secondary);font-size:10px}.native-query-log button{color:var(--ks-text-link);font-size:10px}.native-query-log pre{margin:8px 0 0;white-space:pre-wrap;font:11px/1.7 monospace}.native-query-log .error,.error{color:#df7490}.summary{display:flex;align-items:center;gap:16px;padding:25px 0;border-bottom:1px solid var(--ks-border-default)}.summary>strong{font-size:40px;font-weight:500}.summary small{display:block;margin-top:5px}.summary-columns{display:grid;grid-template-columns:1fr 1fr;gap:40px;padding:20px 0}.summary-columns h3{font-size:11px;text-transform:uppercase;color:var(--ks-text-secondary)}.summary-state{display:flex;width:100%;align-items:center;gap:15px;position:relative;min-height:35px;border-bottom:1px solid var(--ks-border-default);font-size:11px;text-align:left}.summary-state>span{min-width:120px}.summary-state>b{margin-left:auto}.summary-state>i{height:4px;max-width:50%;background:var(--ks-text-link);border-radius:2px}.limits{display:grid;grid-template-columns:repeat(3,1fr);padding:18px 0;border-top:1px solid var(--ks-border-default)}.limits b{display:block;font-size:24px;margin-top:6px;font-weight:500}.note,.empty{color:var(--ks-text-secondary);font-size:11px;line-height:1.7}.empty{padding:40px 0}footer{display:flex;align-items:center;gap:10px;padding-top:15px}footer small{margin-right:auto;max-width:65%;line-height:1.6}.duration{margin-top:22px;border-top:1px solid var(--ks-border-default);padding-top:14px}.duration h3{font-size:12px;margin:14px 0}.duration-values{display:flex;align-items:center;gap:30px;flex-wrap:wrap;margin:12px 0;font-size:11px}.duration-values b{margin-left:9px}.duration>small{display:block;font-size:10px;line-height:1.6;color:var(--ks-text-secondary)}.trend-svg{display:block;width:100%;height:150px}.trend-labels{display:flex;justify-content:space-between;gap:10px;font-size:10px;color:var(--ks-text-secondary)}</style>
